<template><div class="page-container"><div class="page-head"><div><h2 class="page-title">司南推广链</h2><p class="page-subtitle">数据来自司南，推广链可直接带入批量投放。</p></div><el-button type="primary" @click="load">刷新</el-button></div><el-alert v-if="!verified" type="warning" show-icon title="司南账号尚未验证，请先完成司南配置"/><el-card v-else shadow="never"><el-table :data="items" v-loading="loading"><el-table-column prop="promotion_name" label="推广链名称"/><el-table-column prop="drama_title" label="推广内容"/><el-table-column prop="chapter_title" label="跳转节点"/><el-table-column prop="ad_group" label="广告组"/><el-table-column prop="landing_url" label="推广链接" show-overflow-tooltip/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="show(row)">查看链接</el-button><el-button link type="success" @click="use(row)">去投放</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="暂无司南推广链"/></el-card><el-dialog v-model="dialog" title="推广链详情" width="620px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="广告系列">{{current.promotion_name||'-'}}</el-descriptions-item><el-descriptions-item label="广告组">{{current.ad_group||'-'}}</el-descriptions-item><el-descriptions-item label="推广链接">{{current.landing_url||'-'}}</el-descriptions-item></el-descriptions></el-dialog></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {sinanApi} from '@/api/sinan';import {sinanPromotionsApi,type SinanPromotion} from '@/api/sinanPromotions';const router=useRouter(),items=ref<SinanPromotion[]>([]),loading=ref(false),verified=ref(false),dialog=ref(false),current=ref<SinanPromotion|null>(null);async function load(){loading.value=true;try{verified.value=!!(await sinanApi.status()).data.verified;if(verified.value){const d=(await sinanPromotionsApi.list()).data;items.value=d.Promotions||d.items||[]}}finally{loading.value=false}}function show(r:SinanPromotion){current.value=r;dialog.value=true}function use(r:SinanPromotion){router.push({path:'/dashboard/batch-publish',query:{sinan_promotion_id:r.promotion_id}})}onMounted(load)</script>
